  1→const { errors: formidableErrors } = require('formidable');
  2→const {
  3→  sendAcceptedResponse,
  4→  sendOkResponse,
  5→  sendErrorResponse,
  6→  sendResponse,
  7→  sendBadRequestResponse,
  8→  sendNotFoundResponse,
  9→} = require('../core/responses.js');
 10→const { uploadMedia } = require('../actions/uploadMedia.js');
 11→const { convertBytesToMb } = require('../core/utils.js');
 12→const {
 13→  MAX_FILE_SIZE,
 14→  CUSTOM_FORMIDABLE_ERRORS,
 15→  MEDIA_STATUS,
 16→} = require('../core/constants.js');
 17→const { copyMediaFile, getProcessedMediaUrl } = require('../clients/s3.js');
 18→const { createMedia, getMedia, setMediaStatus } = require('../clients/dynamodb.js');
 19→const { getLogger } = require('../logger.js');
 20→const {
 21→  publishDeleteMediaEvent,
 22→  publishResizeMediaEvent,
 23→} = require('../clients/sns.js');
 24→
 25→const logger = getLogger();
 26→
 27→const uploadController = async (req, res) => {
 28→  try {
 29→    const { mediaId, file } = await uploadMedia(req);
 30→    const { size, originalFilename: name, mimetype } = file;
 31→    const { width } = req.hummingbirdOptions;
 32→
 33→    await createMedia({ mediaId, size, name, mimetype, width });
 34→    // Kick off async processing (handled by the background worker subscribed to media events)
 35→    await publishResizeMediaEvent({ mediaId, width });
 36→
 37→    sendAcceptedResponse(res, { mediaId });
 38→  } catch (error) {
 39→    if (error.httpCode && error.code) {
 40→      if (error.code === formidableErrors.biggerThanTotalMaxFileSize) {
 41→        const maxFileSize = convertBytesToMb(MAX_FILE_SIZE);
 42→        let message = `Failed to upload media. Check the file size. Max size is ${maxFileSize} MB.`;
 43→        sendResponse(res, error.httpCode, message);
 44→        return;
 45→      }
 46→
 47→      if (error.code === formidableErrors.maxFilesExceeded) {
 48→        sendBadRequestResponse(res, {
 49→          message:
 50→            'Too many fields in the form. Only single file uploads are supported.',
 51→        });
 52→        return;
 53→      }
 54→
 55→      if (error.code === formidableErrors.malformedMultipart) {
 56→        sendBadRequestResponse(res, {
 57→          message: 'Malformed multipart form data.',
 58→        });
 59→        return;
 60→      }
